","/**
 * Executes an array of task functions with a concurrency limit.
 * Each task is a function that returns a Promise.
 */
export async function executeWithConcurrency<T>(
  tasks: (() => Promise<T>)[],
  concurrency: number
): Promise<T[]> {
  if (tasks.length === 0) {
    return [];
  }

  // Ensure concurrency is at least 1
  const limit = Math.max(1, Math.floor(concurrency));

  const results: T[] = new Array(tasks.length);
  let currentIndex = 0;

  async function runNext(): Promise<void> {
    while (currentIndex < tasks.length) {
      const index = currentIndex++;
      results[index] = await tasks[index]();
    }
  }

  const workers = Array.from({ length: Math.min(limit, tasks.length) }, () =>
    runNext()
  );

  await Promise.all(workers);
  return results;
}

/**
 * Encode an object key for use in an S3-style request path or
 * `X-Amz-Copy-Source` header. Encodes each path segment with
 * AWS-compatible URI escaping and rejoins with `/`, so the slash
 * separators survive verbatim.
 *
 * Why not bare `encodeURIComponent`: AWS's SigV4 canonical-URI scheme
 * (and the S3 gateway's server-side canonicalization) percent-encode
 * every byte except `A-Za-z0-9-._~` — that includes the sub-delims
 * `!'()*`, which `encodeURIComponent` leaves alone. If we sign and
 * send a path with literal `(` but the server canonicalizes it to
 * `%28` before checking, we get `SignatureDoesNotMatch` on keys that
 * contain those characters (e.g. `holiday (2024).jpg`).
 *
 * The slash-preserving split also matters: a single `encodeURIComponent`
 * on the whole key would turn `/` into `%2F`, which the signer or server
 * would then encode again to `%252F` — same divergence symptom.
 */
export function encodeObjectKey(key: string): string {
  return key.split('/').map(escapeUriSegment).join('/');
}

/** AWS-compatible URI escape for a single path segment. */
function escapeUriSegment(segment: string): string {
  return encodeURIComponent(segment).replace(
    /[!'()*]/g,
    (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`
  );
}

export function toError(value: unknown): Error {
  if (value instanceof Error) return value;
  if (typeof value === 'string') return new Error(value);
  return new Error('An unexpected error occurred');
}

export const handleError = (error: Error) => {
  let errorMessage: string | undefined;

  if ((error as { Code?: string }).Code === 'AccessDenied') {
    errorMessage = 'Access denied. Please check your credentials.';
  }
  if ((error as { Code?: string }).Code === 'NoSuchKey') {
    errorMessage = 'File not found in Tigris Storage';
  }

  if (errorMessage) {
    return {
      error: new Error(errorMessage),
    };
  }

  return {
    error: new Error(
      error?.message || 'Unexpected error while processing request'
    ),
  };
};
","export const addRandomSuffix = (path: string) => {
  const pathParts = path.split('.');
  const extension = pathParts.length > 1 ? pathParts.pop() : '';
  const baseName = pathParts.join('.');
  return `${baseName}-${Date.now().toString(36) + Math.random().toString(36).substring(2, 8)}${extension ? `.${extension}` : ''}`;
};
","import { executeWithConcurrency } from '@shared/utils';
import type { TigrisStorageResponse } from '../types';
import { addRandomSuffix } from '../utils';
import { type SignedUploadUrlResponse, UploadAction } from './shared';

export type UploadOptions = {
  access?: 'public' | 'private';
  addRandomSuffix?: boolean;
  allowOverwrite?: boolean;
  contentType?: string;
  contentDisposition?: 'attachment' | 'inline';
  url?: string;
  multipart?: boolean;
  partSize?: number;
  /**
   * Maximum number of concurrent part uploads for multipart uploads
   * @default 4
   */
  concurrency?: number;
  onUploadProgress?: (progress: UploadProgress) => void;
};

export type UploadProgress = {
  loaded: number;
  total: number;
  percentage: number;
};

export type UploadResponse = {
  contentDisposition?: string;
  contentType?: string;
  modified: Date;
  name: string;
  size: number;
  url: string;
};

export async function upload(
  name: string,
  data: File | Blob,
  options?: UploadOptions
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  if (!options?.url) {
    return {
      error: new Error('URL option is required for client uploads'),
    };
  }

  if (options?.addRandomSuffix) {
    name = addRandomSuffix(name);
  }

  const partSize = options?.partSize ?? 5 * 1024 * 1024; // 5MB default

  if (options?.multipart) {
    return uploadMultipart(name, data, options, partSize);
  } else {
    return uploadSingle(name, data, options);
  }
}

async function uploadSingle(
  name: string,
  data: File | Blob,
  options?: UploadOptions
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  if (!options?.url) {
    return {
      error: new Error('URL option is required for client uploads'),
    };
  }

  try {
    // Get presigned URL
    const presignedResponse = await fetch(options.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name,
        action: UploadAction.SinglepartInit,
        operation: 'put',
        contentType: options?.contentType ?? data.type,
      }),
    });

    // Check if presigned URL is valid
    if (!presignedResponse.ok) {
      return {
        error: new Error(
          `Failed to get presigned URL: ${presignedResponse.statusText}`
        ),
      };
    }

    // Get presigned URL
    const response = await presignedResponse.json();

    if (!response.data?.url) {
      return {
        error: new Error('Failed to get presigned URL'),
      };
    }

    const presignedUrl = response.data.url;

    // Upload file
    return new Promise<void>((resolve, reject) => {
      const xhr = new XMLHttpRequest();

      // Track progress
      xhr.upload.addEventListener('progress', (event) => {
        if (event.lengthComputable && options?.onUploadProgress) {
          const percentage = Math.round((event.loaded / event.total) * 100);
          options.onUploadProgress({
            loaded: event.loaded,
            total: event.total,
            percentage,
          });
        }
      });

      // Handle success
      xhr.addEventListener('load', () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          resolve();
        } else {
          reject(new Error(`Upload failed with status: ${xhr.status}`));
        }
      });

      // Handle error
      xhr.addEventListener('error', () => {
        reject(new Error('Upload failed due to network error'));
      });

      // Open request
      xhr.open('PUT', presignedUrl);

      if (options?.contentType || data.type) {
        xhr.setRequestHeader('Content-Type', options?.contentType ?? data.type);
      }

      // Send data
      xhr.send(data);
    })
      .then(() => {
        // Return response
        return {
          data: {
            contentDisposition: options?.contentDisposition,
            contentType: options?.contentType ?? data.type,
            modified: new Date(),
            name,
            size: data.size,
            url: presignedUrl.replace('x-id=PutObject', 'x-id=GetObject'),
          },
        };
      })
      .catch((error) => {
        // Return error
        return {
          error: new Error(error),
        };
      });
  } catch {
    // Return error
    return {
      error: new Error('Single upload failed'),
    };
  }
}

async function uploadMultipart(
  name: string,
  data: File | Blob,
  options?: UploadOptions,
  partSize: number = 5 * 1024 * 1024
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  if (!options?.url) {
    return {
      error: new Error('URL option is required for client uploads'),
    };
  }

  try {
    // Step 1: Initialize multipart upload via API endpoint
    const initResponse = await fetch(options.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name,
        action: UploadAction.MultipartInit,
        contentType: options?.contentType ?? data.type,
      }),
    });

    if (!initResponse.ok) {
      return {
        error: new Error(
          `Failed to initialize multipart upload: ${initResponse.statusText}`
        ),
      };
    }

    const { data: initData } = await initResponse.json();
    const { uploadId } = initData;

    // Step 2: Split file into parts and get presigned URLs
    const totalParts = Math.ceil(data.size / partSize);
    const parts = Array.from({ length: totalParts }, (_, i) => i + 1);

    const urlResponse = await fetch(options.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name,
        action: UploadAction.MultipartGetParts,
        uploadId,
        parts,
      }),
    });

    if (!urlResponse.ok) {
      return {
        error: new Error(`Failed to get part URLs: ${urlResponse.statusText}`),
      };
    }

    const { data: urlData } = await urlResponse.json();
    const partUrls = urlData;

    // Step 3: Upload parts with progress tracking and concurrency limit
    const concurrency = options?.concurrency ?? 4;
    const partProgress = new Map<number, number>();

    const calculateTotalProgress = () => {
      let total = 0;
      for (const bytes of partProgress.values()) {
        total += bytes;
      }
      return total;
    };

    const uploadTasks = partUrls.map(
      ({ part, url }: { part: number; url: string }, index: number) => {
        return () => {
          const start = index * partSize;
          const end = Math.min(start + partSize, data.size);
          const chunk = data.slice(start, end);

          // Initialize progress for this part
          partProgress.set(part, 0);

          return new Promise<Record<number, string>>((resolve, reject) => {
            const xhr = new XMLHttpRequest();

            xhr.upload.addEventListener('progress', (event) => {
              if (event.lengthComputable && options?.onUploadProgress) {
                partProgress.set(part, event.loaded);
                const currentTotal = calculateTotalProgress();
                const percentage = Math.round((currentTotal / data.size) * 100);

                options.onUploadProgress({
                  loaded: currentTotal,
                  total: data.size,
                  percentage,
                });
              }
            });

            xhr.addEventListener('load', () => {
              if (xhr.status >= 200 && xhr.status < 300) {
                partProgress.set(part, chunk.size);
                const currentTotal = calculateTotalProgress();
                options?.onUploadProgress?.({
                  loaded: currentTotal,
                  total: data.size,
                  percentage: Math.round((currentTotal / data.size) * 100),
                });
                resolve({ [part]: xhr.getResponseHeader('ETag') ?? '' });
              } else {
                reject(
                  new Error(
                    `Part ${part} upload failed with status: ${xhr.status}`
                  )
                );
              }
            });

            xhr.addEventListener('error', () => {
              reject(
                new Error(`Part ${part} upload failed due to network error`)
              );
            });

            xhr.open('PUT', url);
            xhr.send(chunk);
          });
        };
      }
    );

    const partIds = await executeWithConcurrency(uploadTasks, concurrency);

    // Step 4: Complete multipart upload
    const completeResponse = await fetch(options.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name,
        action: UploadAction.MultipartComplete,
        uploadId,
        partIds,
      }),
    });

    if (!completeResponse.ok) {
      return {
        error: new Error(
          `Failed to complete multipart upload: ${completeResponse.statusText}`
        ),
      };
    }

    const { data: completeData } = await completeResponse.json();

    return {
      data: {
        contentDisposition: options?.contentDisposition,
        contentType: options?.contentType ?? data.type,
        modified: new Date(),
        name,
        size: data.size,
        url: completeData?.url ?? '',
      },
    };
  } catch (error) {
    return {
      error: new Error(
        `Multipart upload failed: ${error instanceof Error ? error.message : 'Unknown error'}`
      ),
    };
  }
}

export type UploadToSignedUrlOptions = {
  contentType?: string;
  onUploadProgress?: (progress: UploadProgress) => void;
};

/**
 * Uploads a file using the contract returned by `getSignedUploadUrl`.
 * Branches on `signed.method`: PUT sends the body as the request payload
 * (applying any required headers), POST submits a multipart/form-data
 * body with the policy `fields` followed by the `file` input.
 */
export async function uploadToSignedUrl(
  name: string,
  data: File | Blob,
  signed: SignedUploadUrlResponse,
  options?: UploadToSignedUrlOptions
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  if (signed.method === 'PUT') {
    return uploadToPutUrl(name, data, signed, options);
  }
  return uploadToPostUrl(name, data, signed, options);
}

function trackProgress(
  xhr: XMLHttpRequest,
  total: number,
  onUploadProgress?: (progress: UploadProgress) => void
): void {
  if (!onUploadProgress) return;
  xhr.upload.addEventListener('progress', (event) => {
    if (event.lengthComputable) {
      onUploadProgress({
        loaded: event.loaded,
        total: event.total,
        percentage: Math.round((event.loaded / event.total) * 100),
      });
    } else {
      onUploadProgress({
        loaded: event.loaded,
        total,
        percentage: total > 0 ? Math.round((event.loaded / total) * 100) : 0,
      });
    }
  });
}

async function uploadToPutUrl(
  name: string,
  data: File | Blob,
  signed: Extract<SignedUploadUrlResponse, { method: 'PUT' }>,
  options?: UploadToSignedUrlOptions
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  const contentType =
    options?.contentType ?? signed.headers?.['Content-Type'] ?? data.type;

  return new Promise<TigrisStorageResponse<UploadResponse, Error>>(
    (resolve) => {
      const xhr = new XMLHttpRequest();
      trackProgress(xhr, data.size, options?.onUploadProgress);

      xhr.addEventListener('load', () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          resolve({
            data: {
              contentType,
              modified: new Date(),
              name,
              size: data.size,
              url: signed.url.replace('x-id=PutObject', 'x-id=GetObject'),
            },
          });
        } else {
          resolve({
            error: new Error(`Upload failed with status: ${xhr.status}`),
          });
        }
      });

      xhr.addEventListener('error', () => {
        resolve({ error: new Error('Upload failed due to network error') });
      });

      xhr.open('PUT', signed.url);

      // XHR's setRequestHeader merges repeated calls for the same name
      // (per spec), which would produce `Content-Type: a, b` and break
      // the SigV4 check. Set Content-Type exactly once.
      if (signed.headers) {
        for (const [k, v] of Object.entries(signed.headers)) {
          if (k.toLowerCase() === 'content-type') continue;
          xhr.setRequestHeader(k, v);
        }
      }
      const resolvedContentType =
        options?.contentType ?? signed.headers?.['Content-Type'] ?? data.type;
      if (resolvedContentType) {
        xhr.setRequestHeader('Content-Type', resolvedContentType);
      }

      xhr.send(data);
    }
  );
}

async function uploadToPostUrl(
  name: string,
  data: File | Blob,
  signed: Extract<SignedUploadUrlResponse, { method: 'POST' }>,
  options?: UploadToSignedUrlOptions
): Promise<TigrisStorageResponse<UploadResponse, Error>> {
  const form = new FormData();
  for (const [k, v] of Object.entries(signed.fields)) {
    form.append(k, v);
  }
  // `file` must be appended last per S3 POST policy semantics.
  form.append('file', data);

  return new Promise<TigrisStorageResponse<UploadResponse, Error>>(
    (resolve) => {
      const xhr = new XMLHttpRequest();
      trackProgress(xhr, data.size, options?.onUploadProgress);

      xhr.addEventListener('load', () => {
        // POST policy returns 204 by default, or 3xx when
        // success_action_redirect is set. XHR normally follows the
        // redirect, but accept 2xx-3xx defensively for implementations
        // that don't (and so a redirect target's status doesn't get
        // mis-reported as an S3 rejection).
        if (xhr.status >= 200 && xhr.status < 400) {
          resolve({
            data: {
              contentType:
                options?.contentType ??
                signed.fields['Content-Type'] ??
                data.type,
              modified: new Date(),
              name,
              size: data.size,
              // Object location. POST policy has no signed-GET equivalent,
              // so callers wanting auth-bearing reads should use
              // `getPresignedUrl({ operation: 'get' })`.
              url: new URL(signed.fields.key ?? name, signed.url).toString(),
            },
          });
        } else {
          resolve({
            error: new Error(`Upload failed with status: ${xhr.status}`),
          });
        }
      });

      xhr.addEventListener('error', () => {
        resolve({ error: new Error('Upload failed due to network error') });
      });

      xhr.open('POST', signed.url);
      xhr.send(form);
    }
  );
}
